//! Cross-validation of the Rust dynamic client against the TypeScript
//! `@codama/dynamic-client` implementation, using the real SPL Token and
//! Token-2022 IDLs.
//!
//! `tests/fixtures/spl-reference-vectors.json` is generated by the TypeScript
//! test `packages/dynamic-client/test/programs/dump-reference-vectors.test.ts`,
//! which builds each instruction with the canonical TS client and records the
//! resulting instruction data and account metas. This test rebuilds the same
//! instructions from the same IDLs with the Rust client and asserts byte- and
//! role-for-role equality. The encoded bytes also match the canonical on-chain
//! SPL Token wire format (e.g. `transfer` = tag `03` + amount u64 LE).

use codama_dynamic_client::{
    get_instruction_display, Instruction, InstructionDisplay, ProgramClient, Value,
};
use serde::Deserialize;
use std::collections::HashMap;

#[derive(Deserialize)]
struct RefAccount {
    address: String,
    #[serde(rename = "isSigner")]
    is_signer: bool,
    #[serde(rename = "isWritable")]
    is_writable: bool,
}

#[derive(Deserialize)]
struct RefVector {
    program: String,
    label: String,
    method: String,
    #[serde(rename = "dataHex")]
    data_hex: String,
    accounts: Vec<RefAccount>,
}

/// Deterministic pubkey: 32 bytes filled with `n`. Matches the TypeScript
/// `getAddressDecoder().decode(new Uint8Array(32).fill(n))`.
fn a(n: u8) -> codama_dynamic_client::Pubkey {
    codama_dynamic_client::Pubkey::new_from_array([n; 32])
}

fn pubkey_value(n: u8) -> Value {
    Value::PublicKey([n; 32])
}

/// Builds the instruction for the given label, matching the TypeScript inputs in
/// `dump-reference-vectors.test.ts`.
fn build(
    token: &ProgramClient,
    token2022: &ProgramClient,
    program: &str,
    label: &str,
) -> Instruction {
    let client = match program {
        "token" => token,
        "token-2022" => token2022,
        other => panic!("unknown program {other}"),
    };
    let result = match label {
        "transfer" => client
            .method("transfer")
            .unwrap()
            .argument("amount", 400_000u64)
            .account("source", a(2))
            .account("destination", a(3))
            .account("authority", a(4))
            .signer("authority")
            .build(),
        "approve" => client
            .method("approve")
            .unwrap()
            .argument("amount", 1_000u64)
            .account("source", a(2))
            .account("delegate", a(5))
            .account("owner", a(4))
            .signer("owner")
            .build(),
        "revoke" => client
            .method("revoke")
            .unwrap()
            .account("source", a(2))
            .account("owner", a(4))
            .signer("owner")
            .build(),
        "mintTo" => client
            .method("mintTo")
            .unwrap()
            .argument("amount", 1_000_000u64)
            .account("mint", a(6))
            .account("token", a(2))
            .account("mintAuthority", a(4))
            .signer("mintAuthority")
            .build(),
        "burn" => client
            .method("burn")
            .unwrap()
            .argument("amount", 500u64)
            .account("account", a(2))
            .account("authority", a(4))
            .account("mint", a(6))
            .signer("authority")
            .build(),
        "closeAccount" => client
            .method("closeAccount")
            .unwrap()
            .account("account", a(2))
            .account("destination", a(3))
            .account("owner", a(4))
            .signer("owner")
            .build(),
        "transferChecked" => client
            .method("transferChecked")
            .unwrap()
            .argument("amount", 400_000u64)
            .argument("decimals", 9u8)
            .account("source", a(2))
            .account("mint", a(6))
            .account("destination", a(3))
            .account("authority", a(4))
            .signer("authority")
            .build(),
        "amountToUiAmount" => client
            .method("amountToUiAmount")
            .unwrap()
            .argument("amount", 123_456u64)
            .account("mint", a(6))
            .build(),
        "initializeMint:none" => client
            .method("initializeMint")
            .unwrap()
            .argument("decimals", 9u8)
            .argument("mintAuthority", pubkey_value(4))
            .argument("freezeAuthority", Value::Option(None))
            .account("mint", a(6))
            .build(),
        "initializeMint:some" => client
            .method("initializeMint")
            .unwrap()
            .argument("decimals", 6u8)
            .argument("mintAuthority", pubkey_value(4))
            .argument(
                "freezeAuthority",
                Value::Option(Some(Box::new(pubkey_value(7)))),
            )
            .account("mint", a(6))
            .build(),
        "setAuthority:some" => client
            .method("setAuthority")
            .unwrap()
            .argument("authorityType", Value::unit_enum("mintTokens"))
            .argument(
                "newAuthority",
                Value::Option(Some(Box::new(pubkey_value(8)))),
            )
            .account("owned", a(2))
            .account("owner", a(4))
            .signer("owner")
            .build(),
        "setAuthority:none" => client
            .method("setAuthority")
            .unwrap()
            .argument("authorityType", Value::unit_enum("closeAccount"))
            .argument("newAuthority", Value::Option(None))
            .account("owned", a(2))
            .account("owner", a(4))
            .signer("owner")
            .build(),
        other => panic!("unhandled label {other}"),
    };
    result.unwrap_or_else(|e| panic!("failed to build {program}::{label}: {e}"))
}

#[test]
fn rust_client_matches_typescript_reference_vectors() {
    let token = ProgramClient::from_json(include_str!("fixtures/token-idl.json")).unwrap();
    let token2022 = ProgramClient::from_json(include_str!("fixtures/token-2022-idl.json")).unwrap();

    let vectors: Vec<RefVector> =
        serde_json::from_str(include_str!("fixtures/spl-reference-vectors.json")).unwrap();
    assert_eq!(vectors.len(), 16, "expected 16 reference vectors");

    for vector in &vectors {
        let ix = build(&token, &token2022, &vector.program, &vector.label);
        let context = format!("{}::{}", vector.program, vector.label);

        // Instruction data must match byte-for-byte.
        assert_eq!(
            hex::encode(&ix.data),
            vector.data_hex,
            "data mismatch for {context}"
        );

        // Account metas must match in order, address and role.
        assert_eq!(
            ix.accounts.len(),
            vector.accounts.len(),
            "account count mismatch for {context}"
        );
        for (i, (actual, expected)) in ix.accounts.iter().zip(&vector.accounts).enumerate() {
            assert_eq!(
                actual.pubkey.to_string(),
                expected.address,
                "account[{i}] address mismatch for {context}"
            );
            assert_eq!(
                actual.is_signer, expected.is_signer,
                "account[{i}] is_signer mismatch for {context}"
            );
            assert_eq!(
                actual.is_writable, expected.is_writable,
                "account[{i}] is_writable mismatch for {context}"
            );
        }

        // Round-trip: the parser must identify the originating instruction from
        // the very bytes the builder produced (token instructions carry a field
        // discriminator on the `discriminator` argument).
        let client = if vector.program == "token" {
            &token
        } else {
            &token2022
        };
        let parsed = client
            .parse_instruction_data(&ix.data)
            .unwrap()
            .unwrap_or_else(|| panic!("parser did not identify {context}"));
        match parsed.path.last() {
            Some(codama_nodes::Node::Instruction(node)) => assert_eq!(
                node.name.as_str(),
                vector.method,
                "parser identified the wrong instruction for {context}"
            ),
            other => panic!("expected an instruction node for {context}, got {other:?}"),
        }

        if vector.program == "token-2022" && vector.label == "transferChecked" {
            let display = render(client, &ix);
            let expected = format!("Transfer 0.0004 {} from {} to {}", a(6), a(2), a(3));
            assert_eq!(display.intent, "Transfer tokens");
            assert_eq!(
                display.interpolated_intent.as_deref(),
                Some(expected.as_str())
            );
            assert!(
                display.fields.iter().all(|f| f.label != "Decimals"),
                "decimals was already injected into the amount: {display:?}"
            );
            assert_eq!(field(&display, "Amount"), "0.0004");
            assert_eq!(field(&display, "From"), a(2).to_string());
            assert_eq!(field(&display, "To"), a(3).to_string());
        }
    }

    let transfer = build(&token, &token2022, "token-2022", "transfer");
    let display = render(&token2022, &transfer);
    let expected = format!("Transfer 400000 base units from {} to {}", a(2), a(3));
    assert_eq!(display.intent, "Transfer tokens");
    assert_eq!(
        display.interpolated_intent.as_deref(),
        Some(expected.as_str())
    );
    assert!(display.fields.iter().all(|f| f.label != "Discriminator"));
    assert_eq!(field(&display, "Amount"), "400000 base units");
    assert_eq!(field(&display, "From"), a(2).to_string());
    assert_eq!(field(&display, "To"), a(3).to_string());
    assert_eq!(field(&display, "Authority"), a(4).to_string());

    let init = build(&token, &token2022, "token-2022", "initializeMint:none");
    let parsed = token2022.parse_instruction(&init).unwrap().unwrap();
    assert!(
        parsed.accounts.iter().any(|account| account.name == "rent"),
        "rent must stay on the instruction even though display skips it"
    );
    let display =
        get_instruction_display(token2022.root(), &parsed, &HashMap::new(), &HashMap::new())
            .unwrap();
    assert_eq!(display.intent, "Initialize mint");
    let expected = format!("Initialize mint {} with 9 decimals", a(6));
    assert_eq!(
        display.interpolated_intent.as_deref(),
        Some(expected.as_str())
    );
    assert!(display
        .fields
        .iter()
        .all(|f| f.label != "Rent" && f.label != "Discriminator"));
    assert_eq!(field(&display, "Decimals"), "9");
    assert_eq!(field(&display, "Mint Authority"), a(4).to_string());
    assert_eq!(field(&display, "Freeze Authority"), "None");
    assert_eq!(field(&display, "Mint"), a(6).to_string());
}

fn render(client: &ProgramClient, ix: &Instruction) -> InstructionDisplay {
    let parsed = client.parse_instruction(ix).unwrap().unwrap();
    get_instruction_display(client.root(), &parsed, &HashMap::new(), &HashMap::new()).unwrap()
}

fn field<'a>(display: &'a InstructionDisplay, label: &str) -> &'a str {
    display
        .fields
        .iter()
        .find(|f| f.label == label)
        .unwrap_or_else(|| panic!("missing field {label} in {display:?}"))
        .value
        .as_str()
}
